/// Build a fresh in-memory [`Card`] POD from a static [`CardSpec`].
/// `uid` is set to a placeholder which [`spawn_card_into_pile`]
/// overwrites with the next sequential arena slot. Mirrors the Python
/// `CombatState._make_named_card(card_name)` path at
/// `sts2-rl-agent@01c094d:sts2_env/core/combat.py`. Bead `sts2-rs-5om`.
#[must_use]
pub fn card_from_spec(spec: &CardSpec) -> Card {
    Card {
        uid: CardUid::new(u32::MAX).expect("non-zero placeholder; reassigned at spawn"),
        card_id: spec.id,
        cost: sts2_core::CardEnergyCost::new(spec.cost),
        card_type: spec.card_type,
        target_type: spec.target_type,
        upgraded: false,
        base_damage: spec.base_damage,
        base_block: spec.base_block,
        combat_vars: sts2_core::cards::CombatVars::new(),
        enchantments: sts2_core::cards::CardEnchantments::new(),
        tags: tags_for_card_id(spec.id),
        ..Card::pod_defaults()
    }
}

/// Static `CardId` → `CardTags` mapping. Mirrors the C# `CanonicalTags`
/// HashSet declared on each `CardModel` subclass at
/// `../sts2-wiki/decompiled/v0.103.2/MegaCrit.Sts2.Core.Models.Cards/<Name>.cs`.
/// Previously `card_from_spec` left `Card.tags = CardTags::NONE`, which
/// silently no-op'd every `card.has_tag(CardTag::Strike)` query in real
/// combat (SoldiersStew, FakeStrikeDummy, PerfectedStrike-bonus relics,
/// etc.) — only the test fixture `sample_card` set tags. Bead
/// `sts2-rs-346jo`.
///
/// Audited 2026-05-29 against C# `Models.Cards/*.cs`: 43 cards override
/// `CanonicalTags` with a non-empty set. Every other CardId returns the
/// default `CardTags::NONE`.
#[must_use]
pub fn tags_for_card_id(id: CardId) -> CardTags {
    use CardId as I;
    match id {
        // Strike-tag cards
        I::StrikeIronclad
        | I::StrikeSilent
        | I::StrikeDefect
        | I::StrikeRegent
        | I::StrikeNecrobinder
        | I::PerfectedStrike
        | I::PommelStrike
        | I::SetupStrikeCard
        | I::TwinStrike
        | I::AshenStrike
        | I::LeadingStrike
        | I::FocusedStrikeCard
        | I::MomentumStrike
        | I::AdaptiveStrike
        | I::MeteorStrike
        | I::BlightStrike
        | I::SculptingStrike
        | I::SolarStrike
        | I::ShiningStrike
        | I::SeekerStrike
        | I::UltimateStrike
        // v0.113.0 Fool (`CanonicalTags = { Strike }`).
        | I::StrikeFool
        | I::RhythmStrike
        | I::SorrowfulStrike => CardTags::one(CardTag::Strike),
        // Defend-tag cards
        I::DefendIronclad
        | I::DefendSilent
        | I::DefendDefect
        | I::DefendRegent
        | I::DefendNecrobinder
        | I::UltimateDefend
        | I::DefendFool => CardTags::one(CardTag::Defend),
        // Shiv-tag cards
        I::Shiv => CardTags::one(CardTag::Shiv),
        // Minion-tag cards
        I::MinionDiveBomb | I::MinionSacrifice => CardTags::one(CardTag::Minion),
        // MinionStrike carries BOTH Strike and Minion (C#
        // `MinionStrike.cs:14-18` `CanonicalTags = { Strike, Minion }`) —
        // routes StrikeDummy / FakeStrikeDummy / SoldiersStew and every
        // Minion-tag consumer. Previously fell through to `NONE`.
        I::MinionStrike => CardTags::one(CardTag::Strike).with(CardTag::Minion),
        // OstyAttack-tag cards (Necrobinder pet abilities)
        I::SweepingGaze
        | I::HighFive
        | I::Rattle
        | I::Snap
        | I::BoneShards
        | I::Flatten
        | I::SicEm
        | I::Squeeze
        | I::Fetch
        | I::RightHandHand
        | I::Unleash
        | I::Poke
        | I::Protector => CardTags::one(CardTag::OstyAttack),
        // v0.113.0 Fool melody notes and Shoot (`CanonicalTags`; KiWhip's Ki
        // comes from its `override Tags`, `KiWhip.cs`).
        I::WahBlast | I::WahHammer | I::WahSymphony | I::WahSweep | I::WahTouch => {
            CardTags::one(CardTag::Wah)
        }
        I::ChoBarbsCard | I::ChoChorus | I::ChoFirm | I::ChoLimbs | I::ChoReady => {
            CardTags::one(CardTag::Cho)
        }
        I::KiChant | I::KiHop | I::KiRest | I::KiVerseCard | I::KiWhip => CardTags::one(CardTag::Ki),
        I::WahCho => CardTags::one(CardTag::Wah).with(CardTag::Cho),
        I::WahKi => CardTags::one(CardTag::Wah).with(CardTag::Ki),
        I::ChoKi => CardTags::one(CardTag::Cho).with(CardTag::Ki),
        I::WahChoKi => CardTags::one(CardTag::Wah)
            .with(CardTag::Cho)
            .with(CardTag::Ki),
        I::BlossomShot
        | I::DivineShot
        | I::HeavyShot
        | I::HobblingShot
        | I::FoolishShot
        | I::MelodicShot
        | I::QuickShot
        | I::RainShot
        | I::RapidShot
        | I::RepeatShot
        | I::SkyShot
        | I::TrickShot
        | I::TheShot => CardTags::one(CardTag::Shoot),
        _ => CardTags::NONE,
    }
}

